import{_ as p,a0 as l,w as d,s as c,I as o,x as n,a1 as a,A as i,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Linux DNS 查询剖析（第一部分） | LCTT x X-CMD","titleTemplate":false,"description":"Linux DNS 查询剖析（第一部分） | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux DNS 查询剖析（第一部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux DNS 查询剖析（第一部分） | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180609 Anatomy of a Linux DNS Lookup - Part I","title":"Linux DNS 查询剖析（第一部分）","tag":"201808","desc":""},"relativePath":"201808/20180609 Anatomy of a Linux DNS Lookup - Part I.md","filePath":"[post].md"}'),h={name:"201808/20180609 Anatomy of a Linux DNS Lookup - Part I.md"};function r(g,s,u,f,b,k){const e=l("Link");return d(),c("div",null,[s[34]||(s[34]=o("h1",{id:"linux-dns-查询剖析-第一部分",tabindex:"-1"},[n("Linux DNS 查询剖析（第一部分） "),o("a",{class:"header-anchor",href:"#linux-dns-查询剖析-第一部分","aria-label":"Permalink to “Linux DNS 查询剖析（第一部分）”"},"​")],-1)),o("p",null,[s[7]||(s[7]=n("我经常与虚拟机集群打交道（",-1)),a(e,{href:"https://zwischenzugs.com/2017/10/31/a-complete-chef-infrastructure-on-your-laptop/"},{default:i(()=>[...s[0]||(s[0]=[n("文1",-1)])]),_:1}),s[8]||(s[8]=n("、",-1)),a(e,{href:"https://zwischenzugs.com/2017/03/04/a-complete-openshift-cluster-on-vagrant-step-by-step/"},{default:i(()=>[...s[1]||(s[1]=[n("文2",-1)])]),_:1}),s[9]||(s[9]=n("、",-1)),a(e,{href:"https://zwischenzugs.com/2017/03/04/migrating-an-openshift-etcd-cluster/"},{default:i(()=>[...s[2]||(s[2]=[n("文3",-1)])]),_:1}),s[10]||(s[10]=n("、",-1)),a(e,{href:"https://zwischenzugs.com/2017/03/04/1-minute-multi-node-vm-setup/"},{default:i(()=>[...s[3]||(s[3]=[n("文4",-1)])]),_:1}),s[11]||(s[11]=n("、",-1)),a(e,{href:"https://zwischenzugs.com/2017/03/18/clustered-vm-testing-how-to/"},{default:i(()=>[...s[4]||(s[4]=[n("文5",-1)])]),_:1}),s[12]||(s[12]=n("、",-1)),a(e,{href:"https://zwischenzugs.com/2017/10/27/ten-things-i-wish-id-known-before-using-vagrant/"},{default:i(()=>[...s[5]||(s[5]=[n("文6",-1)])]),_:1}),s[13]||(s[13]=n("），因此最终花费了大量时间试图掌握 ",-1)),a(e,{href:"https://zwischenzugs.com/2017/10/21/openshift-3-6-dns-in-pictures/"},{default:i(()=>[...s[6]||(s[6]=[n("DNS 查询",-1)])]),_:1}),s[14]||(s[14]=n("的工作原理。遇到问题时，我只是不求甚解的使用 StackOverflow 上的“解决方案”，而不知道它们为什么有时工作，有时不工作。",-1))]),s[35]||(s[35]=t('<p>最终我对此感到了厌倦，决定一并找出所有问题的原因。我没有在网上找到完整的指南，我问过一些同事，他们不知所以然（或许是问题太具体了）。</p><p>既然如此，我开始自己写这样的手册。</p><p>结果发现，“Linux 执行一次 DNS 查询”这句话的背后有相当多的工作。</p><p><img src="https://zwischenzugs.files.wordpress.com/2018/06/linux-dns-0.png?w=121" alt="linux-dns-0"></p><p><em>“究竟有多难呢？”</em></p><p><strong>本系列文章试图将 Linux 主机上程序获取（域名对应的） IP 地址的过程及期间涉及的组件进行分块剖析。</strong>如果不理解这些块的协同工作方式，调试解决 <code>dnsmasq</code>、<code>vagrant landrush</code> 和 <code>resolvconf</code> 等相关的问题会让人感到眼花缭乱。</p><p>同时这也是一份有价值的说明，指出原本很简单的东西是如何随着时间的推移变得相当复杂。在弄清楚 DNS 查询的原理的过程中，我了解了大量不同的技术及其发展历程。</p>',7)),o("p",null,[s[16]||(s[16]=n("我甚至编写了一些",-1)),a(e,{href:"https://github.com/ianmiell/shutit-linux-dns/blob/master/linux_dns.py"},{default:i(()=>[...s[15]||(s[15]=[n("自动化脚本",-1)])]),_:1}),s[17]||(s[17]=n("，可以让我在虚拟机中进行实验。欢迎读者参与贡献或勘误。",-1))]),s[36]||(s[36]=t('<p><strong>请注意，本系列主题并不是“DNS 工作原理”</strong>，而是与查询 Linux 主机配置的真实 DNS 服务器（这里假设查询了一台 DNS 服务器，但后面你会看到有时并不需要）相关的内容，以及如何确定使用哪个查询结果，或者如何使用其它方式确定 IP 地址。</p><h3 id="_1-其实并没有名为-dns-查询-的系统调用" tabindex="-1">1) 其实并没有名为“DNS 查询”的系统调用 <a class="header-anchor" href="#_1-其实并没有名为-dns-查询-的系统调用" aria-label="Permalink to “1) 其实并没有名为“DNS 查询”的系统调用”">​</a></h3><p><img src="https://zwischenzugs.files.wordpress.com/2018/06/linux-dns-1.png?w=121" alt="linux-dns-1"></p><p><em>工作方式并非如此</em></p><p><strong>首先要了解的一点是，Linux 上并没有一个单独的方法可以完成 DNS 查询工作</strong>；没有一个有这样的明确接口的核心<ruby>系统调用<rt>system call</rt></ruby>。</p>',5)),o("p",null,[s[19]||(s[19]=n("不过，有一个标准 C 库函数调用 ",-1)),a(e,{href:"http://man7.org/linux/man-pages/man3/getaddrinfo.3.html"},{default:i(()=>[...s[18]||(s[18]=[o("code",null,"getaddrinfo",-1)])]),_:1}),s[20]||(s[20]=n("，不少程序使用了该调用；但不是所有程序或应用都使用该调用！",-1))]),s[37]||(s[37]=t(`<p>让我们看一下两个简单的标准程序：<code>ping</code> 和 <code>host</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxdns1:~# ping -c1 bbc.co.uk | head -1</span></span>
<span class="line"><span>PING bbc.co.uk (151.101.192.81) 56(84) bytes of data.</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxdns1:~# host bbc.co.uk | head -1</span></span>
<span class="line"><span>bbc.co.uk has address 151.101.192.81</span></span></code></pre></div><p>对于同一个域名，两个程序得到的 IP 地址是相同的；那么它们是使用同样的方法得到结果的吧？</p><p>事实并非如此。</p><p>下面文件给出了我主机上 <code>ping</code> 对应的 DNS 相关的系统调用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxdns1:~# strace -e trace=open -f ping -c1 google.com</span></span>
<span class="line"><span>open(&quot;/etc/ld.so.cache&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib/x86_64-linux-gnu/libcap.so.2&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/lib/x86_64-linux-gnu/libc.so.6&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>open(&quot;/etc/resolv.conf&quot;, O_RDONLY|O_CLOEXEC) = 4</span></span>
<span class="line"><span>open(&quot;/etc/resolv.conf&quot;, O_RDONLY|O_CLOEXEC) = 4</span></span>
<span class="line"><span>open(&quot;/etc/nsswitch.conf&quot;, O_RDONLY|O_CLOEXEC) = 4</span></span>
<span class="line"><span>open(&quot;/etc/ld.so.cache&quot;, O_RDONLY|O_CLOEXEC) = 4</span></span>
<span class="line"><span>open(&quot;/lib/x86_64-linux-gnu/libnss_files.so.2&quot;, O_RDONLY|O_CLOEXEC) = 4</span></span>
<span class="line"><span>open(&quot;/etc/host.conf&quot;, O_RDONLY|O_CLOEXEC) = 4</span></span>
<span class="line"><span>open(&quot;/etc/hosts&quot;, O_RDONLY|O_CLOEXEC)  = 4</span></span>
<span class="line"><span>open(&quot;/etc/ld.so.cache&quot;, O_RDONLY|O_CLOEXEC) = 4</span></span>
<span class="line"><span>open(&quot;/lib/x86_64-linux-gnu/libnss_dns.so.2&quot;, O_RDONLY|O_CLOEXEC) = 4</span></span>
<span class="line"><span>open(&quot;/lib/x86_64-linux-gnu/libresolv.so.2&quot;, O_RDONLY|O_CLOEXEC) = 4</span></span>
<span class="line"><span>PING google.com (216.58.204.46) 56(84) bytes of data.</span></span>
<span class="line"><span>open(&quot;/etc/hosts&quot;, O_RDONLY|O_CLOEXEC)  = 4</span></span>
<span class="line"><span>64 bytes from lhr25s12-in-f14.1e100.net (216.58.204.46): icmp_seq=1 ttl=63 time=13.0 ms</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>下面是 <code>host</code> 对应的系统调用:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ strace -e trace=open -f host google.com</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>[pid  9869] open(&quot;/usr/share/locale/en_US.UTF-8/LC_MESSAGES/libdst.cat&quot;, O_RDONLY) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>[pid  9869] open(&quot;/usr/share/locale/en/libdst.cat&quot;, O_RDONLY) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>[pid  9869] open(&quot;/usr/share/locale/en/LC_MESSAGES/libdst.cat&quot;, O_RDONLY) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>[pid  9869] open(&quot;/usr/lib/ssl/openssl.cnf&quot;, O_RDONLY) = 6</span></span>
<span class="line"><span>[pid  9869] open(&quot;/usr/lib/x86_64-linux-gnu/openssl-1.0.0/engines/libgost.so&quot;, O_RDONLY|O_CLOEXEC) = 6[pid  9869] open(&quot;/etc/resolv.conf&quot;, O_RDONLY) = 6</span></span>
<span class="line"><span>google.com has address 216.58.204.46</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>可以看出 <code>ping</code> 打开了 <code>nsswitch.conf</code> 文件，但 <code>host</code> 没有；但两个程序都打开了 <code>/etc/resolv.conf</code> 文件。</p><p>下面我们依次查看这两个 <code>.conf</code> 扩展名的文件。</p><h3 id="_2-nsswitch-与-etc-nsswitch-conf" tabindex="-1">2) NSSwitch 与 <code>/etc/nsswitch.conf</code> <a class="header-anchor" href="#_2-nsswitch-与-etc-nsswitch-conf" aria-label="Permalink to “2) NSSwitch 与 /etc/nsswitch.conf”">​</a></h3><p>我们已经确认应用可以自主决定选用哪个 DNS 服务器。很多应用（例如 <code>ping</code>）通过配置文件 <code>/etc/nsswitch.conf</code> （根据具体实现[^1] ）参考 NSSwitch 完成选择。</p><p>[^1]: <code>ping</code> 实现的变种之多令人惊叹。我 <em>不</em> 希望在这里讨论过多。</p><p>NSSwitch 不仅用于 DNS 查询，例如，还用于密码与用户信息查询。</p><p>NSSwitch 最初是 Solaris OS 的一部分，可以让应用无需硬编码查询所需的文件或服务，而是在其它集中式的、无需应用开发人员管理的配置文件中找到。</p><p>下面是我的 <code>nsswitch.conf</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>passwd:         compat</span></span>
<span class="line"><span>group:          compat</span></span>
<span class="line"><span>shadow:         compat</span></span>
<span class="line"><span>gshadow:        files</span></span>
<span class="line"><span>hosts: files dns myhostname</span></span>
<span class="line"><span>networks:       files</span></span>
<span class="line"><span>protocols:      db files</span></span>
<span class="line"><span>services:       db files</span></span>
<span class="line"><span>ethers:         db files</span></span>
<span class="line"><span>rpc:            db files</span></span>
<span class="line"><span>netgroup:       nis</span></span></code></pre></div><p>我们需要关注的是 <code>hosts</code> 行。我们知道 <code>ping</code> 用到 <code>nsswitch.conf</code> 文件，那么我们修改这个文件（的 <code>hosts</code> 行），看看能够如何影响 <code>ping</code>。</p><h4 id="修改-nsswitch-conf-hosts-行仅保留-files" tabindex="-1">修改 <code>nsswitch.conf</code>， <code>hosts</code> 行仅保留 <code>files</code> <a class="header-anchor" href="#修改-nsswitch-conf-hosts-行仅保留-files" aria-label="Permalink to “修改 nsswitch.conf， hosts 行仅保留 files”">​</a></h4><p>如果你修改 <code>nsswitch.conf</code>，将 <code>hosts</code> 行仅保留 <code>files</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hosts: files</span></span></code></pre></div><p>此时， <code>ping</code> 无法获取 google.com 对应的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c1 google.com</span></span>
<span class="line"><span>ping: unknown host google.com</span></span></code></pre></div><p>但 <code>localhost</code> 的解析不受影响：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c1 localhost</span></span>
<span class="line"><span>PING localhost (127.0.0.1) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from localhost (127.0.0.1): icmp_seq=1 ttl=64 time=0.039 ms</span></span></code></pre></div><p>此外，<code>host</code> 命令正常返回：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ host google.com</span></span>
<span class="line"><span>google.com has address 216.58.206.110</span></span></code></pre></div><p>毕竟如我们之前看到的那样，<code>host</code> 不受 <code>nsswitch.conf</code> 影响。</p><h4 id="修改-nsswitch-conf-hosts-行仅保留-dns" tabindex="-1">修改 <code>nsswitch.conf</code>， <code>hosts</code> 行仅保留 <code>dns</code> <a class="header-anchor" href="#修改-nsswitch-conf-hosts-行仅保留-dns" aria-label="Permalink to “修改 nsswitch.conf， hosts 行仅保留 dns”">​</a></h4><p>如果你修改 <code>nsswitch.conf</code>，将 <code>hosts</code> 行仅保留 <code>dns</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hosts: dns</span></span></code></pre></div><p>此时，google.com 的解析恢复正常：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c1 google.com</span></span>
<span class="line"><span>PING google.com (216.58.198.174) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from lhr25s10-in-f174.1e100.net (216.58.198.174): icmp_seq=1 ttl=63 time=8.01 ms</span></span></code></pre></div><p>但 <code>localhost</code> 无法解析：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c1 localhost</span></span>
<span class="line"><span>ping: unknown host localhost</span></span></code></pre></div><p>下图给出默认 NSSwitch 中 <code>hosts</code> 行对应的查询逻辑：</p><p><img src="https://zwischenzugs.files.wordpress.com/2018/06/linux-dns-2-11.png?w=525" alt="linux-dns-2 (1)"></p><p><em>我的 <code>hosts:</code> 配置是 <code>nsswitch.conf</code> 给出的默认值</em></p><h3 id="_3-etc-resolv-conf" tabindex="-1">3) <code>/etc/resolv.conf</code> <a class="header-anchor" href="#_3-etc-resolv-conf" aria-label="Permalink to “3) /etc/resolv.conf”">​</a></h3><p>我们已经知道 <code>host</code> 和 <code>ping</code> 都使用 <code>/etc/resolv.conf</code> 文件。</p><p>下面给出我主机的 <code>/etc/resolv.conf</code> 文件内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Dynamic resolv.conf(5) file for glibc resolver(3) generated by resolvconf(8)</span></span>
<span class="line"><span>#     DO NOT EDIT THIS FILE BY HAND -- YOUR CHANGES WILL BE OVERWRITTEN</span></span>
<span class="line"><span>nameserver 10.0.2.3</span></span></code></pre></div><p>先忽略前两行，后面我们会回过头来看这部分（它们很重要，但你还需要一些知识储备）。</p><p>其中 <code>nameserver</code> 行指定了查询用到的 DNS 服务器。</p><p>如果将该行注释掉：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#nameserver 10.0.2.3</span></span></code></pre></div><p>再次运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c1 google.com</span></span>
<span class="line"><span>ping: unknown host google.com</span></span></code></pre></div><p>解析失败了，这是因为没有可用的名字服务器 [^2]。</p><p>[^2]: 另一个需要注意的地方： <code>host</code> 在没有指定 nameserver 的情况下会尝试 127.0.0.1:53。</p><p>该文件中还可以使用其它选项。例如，你可以在 <code>resolv.conf</code> 文件中增加如下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>search com</span></span></code></pre></div><p>然后执行 <code>ping google</code> （不写 <code>.com</code>）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping google</span></span>
<span class="line"><span>PING google.com (216.58.204.14) 56(84) bytes of data.</span></span></code></pre></div><p>程序会自动为你尝试 <code>.com</code> 域。</p><h3 id="第一部分总结" tabindex="-1">第一部分总结 <a class="header-anchor" href="#第一部分总结" aria-label="Permalink to “第一部分总结”">​</a></h3><p>第一部分到此结束，下一部分我们会了解 <code>resolv.conf</code> 文件是如何创建和更新的。</p><p>下面总结第一部分涵盖的内容：</p><ul><li>操作系统中并不存在“DNS 查询”这个系统调用</li><li>不同程序可能采用不同的策略获取名字对应的 IP 地址 <ul><li>例如, <code>ping</code> 使用 <code>nsswitch</code>，后者进而使用（或可以使用） <code>/etc/hosts</code>、<code>/etc/resolv.conf</code> 以及主机名得到解析结果</li></ul></li><li><code>/etc/resolv.conf</code> 用于决定： <ul><li>查询什么地址（LCTT 译注：这里可能指 <code>search</code> 带来的影响）</li><li>使用什么 DNS 服务器执行查询</li></ul></li></ul><p>如果你曾认为 DNS 查询很复杂，请跟随这个系列学习吧。</p><hr>`,62)),o("p",null,[s[22]||(s[22]=n("via: ",-1)),a(e,{href:"https://zwischenzugs.com/2018/06/08/anatomy-of-a-linux-dns-lookup-part-i/"},{default:i(()=>[...s[21]||(s[21]=[n("https://zwischenzugs.com/2018/06/08/anatomy-of-a-linux-dns-lookup-part-i/",-1)])]),_:1})]),o("p",null,[s[26]||(s[26]=n("作者：",-1)),a(e,{href:"https://twitter.com/dmatech2"},{default:i(()=>[...s[23]||(s[23]=[n("dmatech",-1)])]),_:1}),s[27]||(s[27]=n(" 译者：",-1)),a(e,{href:"https://github.com/pinewall"},{default:i(()=>[...s[24]||(s[24]=[n("pinewall",-1)])]),_:1}),s[28]||(s[28]=n(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[25]||(s[25]=[n("wxy",-1)])]),_:1})]),o("p",null,[s[31]||(s[31]=n("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[29]||(s[29]=[n("LCTT",-1)])]),_:1}),s[32]||(s[32]=n(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:i(()=>[...s[30]||(s[30]=[n("Linux中国",-1)])]),_:1}),s[33]||(s[33]=n(" 荣誉推出",-1))])])}const O=p(h,[["render",r]]);export{x as __pageData,O as default};
